import type {
  Reporter,
  TestCase,
  TestError,
  TestResult,
  TestStep,
} from "@playwright/test/reporter";

// HTML includes action titles (including fill values) even with traces disabled.
// Only redact ephemeral passwords generated by this E2E runner; retain failures.
const redact = (text: string) =>
  text.replace(/QA-[a-f0-9]{48}(?:-new)?/g, "[REDACTED TEST PASSWORD]");
function error(value: TestError | undefined) {
  if (!value) return;
  if (value.message) value.message = redact(value.message);
  if (value.stack) value.stack = redact(value.stack);
  if (value.snippet) value.snippet = redact(value.snippet);
}
function step(value: TestStep) {
  value.title = redact(value.title);
  error(value.error);
  for (const child of value.steps) step(child);
}
export default class RedactReporter implements Reporter {
  printsToStdio() {
    return false;
  }
  onTestEnd(test: TestCase, result: TestResult) {
    void test;
    for (const value of result.steps) step(value);
    for (const value of result.errors) error(value);
  }
}
